    "contentId": "pf2e:item:equipment-srd:pallesthetic-mutagen",
    "locale": "pt-BR",
    "sourceTranslatableHash": "sha256:bf11403acaecc6d0302aaedcb13a6655d29899ad0de2f9e5b571b2558375e874",
